def pre(xs):
    # The docstring covers every list, including the empty list
    # ("fewer than two distinct values" includes zero values).
    for x in xs:
        if x < -9 or x > 9:
            return False
    return len(xs) <= 6


def post(xs, result):
    # Compute max(xs) independently, if there is one.
    have_max = False
    m = 0
    for x in xs:
        if not have_max or x > m:
            m = x
            have_max = True

    # Find the largest value strictly smaller than max(xs).
    have_second = False
    s = 0
    if have_max:
        for x in xs:
            if x < m:
                if not have_second or x > s:
                    s = x
                    have_second = True

    if not have_second:
        # Fewer than two distinct values (including the empty list).
        return result is None

    if result is None:
        return False
    return result == s
